/**
 * Client-side half of StreamPay's gas sponsorship (issue #57).
 *
 * The contract cannot ask a wallet to sign an inner authorization for a
 * third-party relay, so both parties sign a **canonical claim intent** off
 * chain and an operator submits the transaction (see
 * `contracts/streaming-payments/src/sponsor.rs` for the contract half).
 *
 * This module must rebuild byte-for-byte the `Vec<Val>` the contract
 * reconstructs, because the contract verifies ed25519 signatures over the
 * SHA-256 digest of that XDR. The vector below is generated by the Rust test
 * `canonical_relay_message_has_a_frozen_wire_form`; keep both in sync.
 */
import { Keypair, nativeToScVal, xdr } from "@stellar/stellar-sdk";

/** Domain tag — first element of every signed intent. */
export const CLAIM_DOMAIN_TAG = "StreamPay/sponsored-withdraw/v1";

/** localStorage key holding this browser's beneficiary consent key. */
const CONSENT_KEY_STORE = "streampay.consentKey";

/** The claim the sponsor's operator and the beneficiary both sign. */
export interface ClaimIntent {
  /** Deployed streaming contract id (strkey). */
  contractId: string;
  /** Sponsor address whose budget pays the claim. */
  sponsor: string;
  /** Stream recipient the payout goes to. */
  beneficiary: string;
  /** Payment token of the stream (strkey or classic asset id). */
  token: string;
  streamId: string | bigint;
  /** Payout in smallest token units. */
  amount: string | bigint;
  /** Client-chosen, single-use marker against replays. */
  nonce: string | bigint;
  /** Ledger timestamp after which the intent is void. */
  deadline: number;
}

/**
 * The canonical message: `Vec<Val>` of [domain tag, contract id, sponsor,
 * beneficiary, token, stream id, amount, nonce, deadline], mirroring
 * `sponsor::message` in the contract.
 */
export function claimMessage(intent: ClaimIntent): xdr.ScVal {
  // Built element by element: `nativeToScVal`'s array `types` option does not
  // honor i128, which would silently change the digest the contract verifies.
  const el = (value: unknown, type: string): xdr.ScVal =>
    nativeToScVal(value as never, { type: type as never });
  return xdr.ScVal.scvVec([
    el(CLAIM_DOMAIN_TAG, "string"),
    el(intent.contractId, "string"),
    el(intent.sponsor, "string"),
    el(intent.beneficiary, "string"),
    el(intent.token, "string"),
    el(BigInt(intent.streamId), "u64"),
    el(BigInt(intent.amount), "i128"),
    el(BigInt(intent.nonce), "u64"),
    el(BigInt(intent.deadline), "u64"),
  ]);
}

/** XDR bytes of the canonical message, as hex. */
export function claimMessageHex(intent: ClaimIntent): string {
  return claimMessage(intent).toXDR("hex");
}

function hexToBytes(hex: string): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

/** SHA-256 of the canonical message — the exact bytes the contract verifies. */
export async function claimDigest(intent: ClaimIntent): Promise<Uint8Array> {
  const raw = hexToBytes(claimMessageHex(intent));
  const digest = await crypto.subtle.digest("SHA-256", raw);
  return new Uint8Array(digest);
}

/** Signs the claim digest; returns the 64-byte signature as hex. */
export async function signClaim(
  keypair: Keypair,
  intent: ClaimIntent
): Promise<string> {
  const digest = await claimDigest(intent);
  return bytesToHex(keypair.sign(digest));
}

/**
 * This browser's beneficiary consent key.
 *
 * The contract authenticates sponsored claims with an ed25519 key the
 * beneficiary enrolls (`enroll_beneficiary`), separately from the account that
 * owns the stream. Testnet demo posture: the secret lives in localStorage.
 * A production deployment should keep it in a wallet/hardware signer that can
 * sign raw bytes, and only the public key should ever be persisted here.
 */
export function loadOrCreateConsentKey(): Keypair {
  if (typeof window === "undefined") {
    return Keypair.random();
  }
  const stored = window.localStorage.getItem(CONSENT_KEY_STORE);
  if (stored) {
    try {
      return Keypair.fromSecret(stored);
    } catch {
      window.localStorage.removeItem(CONSENT_KEY_STORE);
    }
  }
  const fresh = Keypair.random();
  window.localStorage.setItem(CONSENT_KEY_STORE, fresh.secret());
  return fresh;
}

/** 32-byte raw public key of a consent key, as hex (contract's BytesN<32>). */
export function consentPublicKeyHex(keypair: Keypair): string {
  return bytesToHex(keypair.rawPublicKey());
}

/**
 * Nonce allocation: the contract accepts a nonce once per
 * `(sponsor, beneficiary)`, so the client must never reuse one — including
 * after a crash. Seed from wall-clock seconds (far above any hand-written
 * nonce) and persist every allocation.
 */
const NONCE_KEY_SEED = 1_000_000_000_000;

export function nextNonce(scope: string): bigint {
  const key = `streampay.nonce.${scope}`;
  const stored =
    typeof window === "undefined" ? null : window.localStorage.getItem(key);
  const wallClock = BigInt(Math.floor(Date.now() / 1000) + NONCE_KEY_SEED);
  const next = stored ? BigInt(stored) + 1n : wallClock;
  if (typeof window !== "undefined") {
    window.localStorage.setItem(key, next.toString());
  }
  return next;
}

/** Marks a nonce as consumed without allocating a new one (relay retries). */
export function peekNonce(scope: string): bigint {
  const key = `streampay.nonce.${scope}`;
  const stored =
    typeof window === "undefined" ? null : window.localStorage.getItem(key);
  if (stored) return BigInt(stored);
  return BigInt(Math.floor(Date.now() / 1000) + NONCE_KEY_SEED);
}

/** Payload the sponsor's relayer endpoint accepts. */
export interface RelayRequest {
  intent: ClaimIntent;
  beneficiarySig: string;
}

export interface RelayResponse {
  txHash: string;
}

/**
 * Asks the sponsor's relay endpoint to submit the signed claim. The operator
 * adds its own signature and pays the Soroban transaction fee.
 */
export async function requestSponsoredClaim(
  relayUrl: string,
  req: RelayRequest
): Promise<RelayResponse> {
  const res = await fetch(relayUrl, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(req),
  });
  const body = (await res.json().catch(() => null)) as
    | (RelayResponse & { error?: string })
    | null;
  if (!res.ok) {
    throw new Error(
      body?.error ? `Relay refused the claim: ${body.error}` : `Relay failed: HTTP ${res.status}`
    );
  }
  if (!body?.txHash) {
    throw new Error("Relay returned no transaction hash");
  }
  return body;
}

/** Default intent lifetime: long enough to survive a slow relayer, short
 * enough that a leaked signature expires quickly. */
export const DEFAULT_INTENT_TTL_SECONDS = 300;

export function intentDeadline(nowSeconds = Math.floor(Date.now() / 1000)): number {
  return nowSeconds + DEFAULT_INTENT_TTL_SECONDS;
}
